import { Bi } from './types';

export type AntimicrobialCategory = 'antibacterial' | 'antiprotozoal_antiparasitic' | 'antifungal_reference';

export type DosageFormType =
  | 'tablet'
  | 'capsule'
  | 'suspension'
  | 'vial_iv_im'
  | 'ampoule'
  | 'infusion'
  | 'eye_ear_drops'
  | 'topical_cream_ointment'
  | 'oral_drops'
  | 'sachet';

export type AdministrationRoute = 'oral' | 'parenteral_iv_im' | 'topical' | 'ophthalmic_otic';

export interface ActiveIngredientRecord {
  id: string;
  nameAr: string;
  nameEn: string;
  category: AntimicrobialCategory;
  drugClass: Bi;
  atcCode: string;
  isCombination: boolean;
  components: string[];
  whoAccessGroup: 'Access' | 'Watch' | 'Reserve';
}

export interface EgyptianCommercialProduct {
  productId: string;
  tradeNameAr: string;
  tradeNameEn: string;
  activeIngredientId: string;
  scientificComposition: string;
  strength: string;
  dosageForm: DosageFormType;
  dosageFormLabel: Bi;
  route: AdministrationRoute;
  routeLabel: Bi;
  packDetails: Bi;
  manufacturer: string;
  countryOfOrigin: string;
  registrationStatus: 'registered_eda' | 'hospital_formulary';
  availabilityStatus: 'available' | 'registered_check_stock' | 'hospital_only';
  priceEgp: number | null;
  unitPriceNote: Bi;
  priceStatus: 'verified_eda' | 'market_observed' | 'unverified';
  priceUpdatedDate: string;
  priceSource: string;
  barcode: string | null;
  barcodeType: 'EAN-13' | 'GS1-GTIN' | 'UNAVAILABLE';
  barcodeStatus: 'verified' | 'unverified_pending';
  barcodeVerifiedBy: string;
  /** Product-specific evidence URL for the barcode verification record. */
  barcodeSourceUrl?: string;
  equivalenceGroupKey: string;
}

