export interface AlternativesClassification {
  exactEquivalents: EgyptianCommercialProduct[];
  sameIngredientDifferentFormOrStrength: EgyptianCommercialProduct[];
  therapeuticClassReference: EgyptianCommercialProduct[];
}

/**
 * Classifies alternatives strictly according to clinical pharmacy standards:
 * 1. Exact generic equivalents (same active ingredient + same strength + same dosage form + same route)
 * 2. Same active ingredient but different strength, dosage form, or pack
 * 3. Different active ingredient within the same pharmacological class (strictly for physician/pharmacist reference only)
 */
export function getClassifiedAlternatives(
  product: EgyptianCommercialProduct,
  allProducts: EgyptianCommercialProduct[] = EGYPTIAN_COMMERCIAL_PRODUCTS
): AlternativesClassification {
  const exactEquivalents = allProducts.filter(
    (p) =>
      p.productId !== product.productId &&
      p.equivalenceGroupKey === product.equivalenceGroupKey
  );

  const sameIngredientDifferentFormOrStrength = allProducts.filter(
    (p) =>
      p.productId !== product.productId &&
      p.activeIngredientId === product.activeIngredientId &&
      p.equivalenceGroupKey !== product.equivalenceGroupKey
  );

  const currentIng = ACTIVE_INGREDIENTS.find((a) => a.id === product.activeIngredientId);
  const therapeuticClassReference = currentIng
    ? allProducts.filter((p) => {
        if (p.activeIngredientId === product.activeIngredientId) return false;
        const otherIng = ACTIVE_INGREDIENTS.find((a) => a.id === p.activeIngredientId);
        return (
          otherIng &&
          otherIng.category === currentIng.category &&
          otherIng.atcCode.slice(0, 4) === currentIng.atcCode.slice(0, 4) &&
          p.route === product.route
        );
      })
    : [];

  return {
    exactEquivalents,
    sameIngredientDifferentFormOrStrength,
    therapeuticClassReference,
  };
}
